INSERT INTO matches VALUES(205393,'31/08/2025','2025-08-31',1217,2174,'fora',3,2,'O arbitro da partida, Rafael Klaus aptou a partida sem criterio nenhum, não dava "faltinha" boba, mas deu um penalti contra o Vasco em que há controversia de sequer o Zagueiro do Vasco tenha tocado no jogador do Sport. Também nesse jogo teve uma falta violenta no Jair, jogador do Vasco em que o jogador se machucou feio no lance, e nem falta o juiz da partida deu no lance. Outro lance bizarro foi um empurrão do jogador do Sport no jogador Lucas Freitas do Vasco cuminando com a saida de bola pela linha de fundo, e o juiz deu escanteio para o time do sport. Tentara de tudo roubar o Vasco, mas mesmo assim, saimos vitoriosos dessa partida.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
