INSERT INTO matches VALUES(205400,'05/10/2025','2025-10-05',4422,2174,'casa',4,3,unistr('O Vitória reclamou da arbitragem, da expulsão do zagueiro Lucas Halter pelo empurrão que ele deu no jogador do Vasco, Paulo Henrique, o jogador expulso já tinha cartão amarelo, então levou outro amarelo e acabou sendo expulso.\u000aOutro lance que não é de hoje é o Léo Jardim querer catimbar o jogo de forma errada e acaba prejudicando o time, ele saiu em uma bola e fico no chão achando que o jogo ia parar, mas o jogo não parou, o Vasco ficou sem goleiro e o Vitória marcou o gol de empate de novo (3 x 3).'),572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
