INSERT INTO matches VALUES(205415,'21/12/2025','2025-12-21',1192,681,'casa',1,2,'O vasco foi vice-campeão da copa do Brasil, um banho de agua de fria para o Vascainos... estava tão perto, mas o Vasco fez o que fez o ano todo, que é dar uma esperança para o torcedor, para achar que vai dar e ter chance de algo, e no final por tudo a perder, foi assim com uma hipotetica vaga no G8 do brasileiro e agora com a copa do brasil, que chegou tão perto, vindo com um empate de São Paulo, e chegar aqui no Rio perder de 2 x 1 para o fraco, devedor, conturbado, impetimado time do corinhians.',572,NULL,'{"substituicoes": [], "reservas_que_entraram": []}','Maracanã','','',NULL,NULL,NULL,'{"arbitro": "", "auxiliares": [], "var": ""}');
INSERT INTO matches VALUES(205416,'15/01/2026','2026-01-15',1206,680,'casa',4,2,'Estreia do Vasco no ano de 2026, bom ataque mas a defesa ainda fragil',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205417,'18/01/2026','2026-01-18',1209,680,'casa',0,0,'O Vasco jogou com time reserva, somente o Leo Jardim de titular que jogou e o Andres Gomes entrou no segundo tempo.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205418,'21/01/2026','2026-01-21',4371,680,'fora',0,1,'O Flamengo estava com 1 ponto no campeonato, precisava ganhar para não disputar mais 2 ou 3 jogos para não cair. Dito isso, por mais que o Vasco estivesse mal, o Flamengo não conseguia fazer gol no Vasco, eis que no começo do segundo tempo o Juiz achou um pretesto para expulsar o melhor marcador do Vasco para facilitar o trabalho do Flamengo, então saiu o gol do Flamengo, mas tenho certeza que se mesmo assim não tivesse saido gol até os 35 min tudo segundo tempo o Juiz do Flamengo certamente iria achar um penalti para o clube da zona sul também.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205419,'25/01/2026','2026-01-25',4477,680,'fora',3,0,'Vasco jogou com time misto, Leo Jardim não jogou pois teve virose. Fuzato entrou no lugar e jogou bem, salvou o Vasco algumas vezes.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205420,'29/01/2026','2026-01-29',1208,2174,'fora',1,2,unistr('Coutinho fez o gol de cabeça e acabou de chocando com o zagueiro, caiu desacordado e quando bateu a cabeça no chão acordou, lance assustador, até quando o Vasco faz gol e doido.\u000aMais uma gol contra dos jogadores que deveriam proteger o gol do Vasco...'),572,12,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205421,'02/02/2026','2026-02-02',4473,680,'fora',0,0,'Jogadores do Vasco sem vontade, jogo moroso.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205422,'05/02/2026','2026-02-05',1246,2174,'casa',1,1,'Vergonhoso jogo do Vasco, atacou e atacou, criou chances, mas todos os jogadores de frente não sabem fazer gols, e no final a Chape empatou.',572,13,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205423,'08/02/2026','2026-02-08',1190,680,'casa',2,0,'Jogo com muita chuva o tempo todo, o gramado enxarcado com muita agua mas não fez piscina.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205424,'11/02/2026','2026-02-11',4362,2174,'casa',0,1,'Time do Vasco horrivel, jogadores sem sangue no modo blazer, um tecnico que se agarra o fato de "jogar bem" mesmo sem vitorias, pior que nem jogar bem está jogando. Mas desse balaio o unico bom jogador e que joga com vontade e é bom jogador é o Andrés Gómez.',572,18,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205425,'14/02/2026','2026-02-14',4480,680,'casa',1,1,'Jogo vergonhoso, Coutinho foi substituido e não gostou, e não voltou para o banco no segundo tempo, pessimo lider, jogo esse que fez o Coutinho pedir pra sair, so pq foi vainhado.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205426,'22/02/2026','2026-02-22',4369,680,'casa',0,1,'Jogo horrivel do Vasco, sem criatividade, sem chutes para o gol, somente passes para tras, time com medo de jogar. Jogo que cuminou na demissão do tecnico Fernando Diniz.',572,NULL,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205427,'26/02/2026','2026-02-26',1216,2174,'fora',1,2,'O Vasco é um clube a deriva, sem tecnico, jogadores perdidos... o time do Santos é horrivel e o Vasco conseguiu perder para eles... vergonha... o Vasco está na lanterna do campeonato.',570,20,'{}','','','',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(205428,'01/03/2026','2026-03-01',4369,680,'fora',1,1,'Jogo em que muitos falam que o Vasco estava com mais raça nesse jogo... mas eu não achei grandes coisas não... o time continua cistando e ciscando mas não faz nada, não chuta a gol, time apatico demais... com esse empate fomos eliminados por um time que sempre foi nosso fregues... O FluC teve um penalti que perdeu, o Vasco fez o gol e teve um penalti a favor e perdu, logo depois o Fluc teve outro penalti que converteu, empandando o jogo e eliminando o Vasco pois o primeiro jogo foi 1 x 1.',570,NULL,'{}','','','',NULL,NULL,NULL,'{}');
