INSERT INTO matches VALUES(206669,'12/03/2026','2026-03-12',4366,2174,'casa',2,1,'Na estreia do tecnico Renato Gaucho, o Vasco ganha de virada.',2439,15,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura", "Tche Tche", "Thiago Mendes"], "Meio-Campista": ["Nuno Moreira"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Puma Rodríguez", "Lucas Freitas", "Cuiabano", "Cauan Barros", "Johan Rojas", "Adson", "Brenner", "Claudio Spinelli", "Marino", "Matheus França"], "nao_relacionados": ["Allan Vitor", "Pablo", "João Vitor", "Walace Falcão", "JP"], "lesionados": ["Carlos Cuesta", "Jair", "Mateus Carvalho"]}','São Januário','19:30','Thiago Mendes',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(206670,'15/03/2026','2026-03-15',4357,2174,'fora',3,3,'Arbitro caseiro, minerão sempre muito violento, policia truculenta, se fosse em São Januario seria interditado alegando falta de segurança.',2439,15,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Cauan Barros", "Hugo Moura", "Tche Tche"], "Meio-Campista": ["Nuno Moreira"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Puma Rodríguez", "Lucas Freitas", "Walace Falcão", "Lucas Piton", "Johan Rojas", "JP", "Adson", "Brenner", "Claudio Spinelli", "Marino", "Matheus França"], "nao_relacionados": ["Allan Vitor", "Pablo", "João Vitor", "Thiago Mendes"], "lesionados": ["Carlos Cuesta", "Jair", "Mateus Carvalho"]}','Mineirão','20:30','Hugo Moura',NULL,NULL,NULL,'{}');
INSERT INTO matches VALUES(206671,'18/03/2026','2026-03-18',4369,2174,'casa',3,2,'Virada do Vasco da Gama, o Vascou jogou mal, tomou gol muito cedo, falha do Hugo Moura, o FluC abriu 2 x 0 mas o Vasco da Gama vira o jogo nos acrescimos do segundo tempo, deixando toda grande midia frustada e triste com o triufo do verdadeiro clube do povo.',2439,10,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Hugo Moura", "Tche Tche", "Thiago Mendes"], "Meio-Campista": ["Nuno Moreira"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Puma Rodríguez", "Carlos Cuesta", "Lucas Freitas", "Lucas Piton", "Johan Rojas", "JP", "Adson", "Brenner", "Claudio Spinelli", "Marino", "Matheus França"], "nao_relacionados": ["Allan Vitor", "Pablo", "João Vitor", "Walace Falcão"], "lesionados": ["Jair", "Mateus Carvalho"], "suspensos": ["Cauan Barros"]}','Maracanã','21:30','Thiago Mendes',NULL,NULL,NULL,'{}');
