INSERT INTO matches VALUES(206674,'04/04/2026','2026-04-04',1190,2174,'casa',1,2,'Achei que a torcida organizada do Vasco pesou a mão em sacanear o Botafogo... um jogo aleatorio do campeonato Brasileiro colocaram mosaico chamando o Botafogo de bairro e listando todas as goleadas, dando armas para eles...em fim ne....',2439,10,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Cauan Barros", "Tche Tche", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Carlos Cuesta", "Lucas Freitas", "Lucas Piton", "Hugo Moura", "JP", "Nuno Moreira", "Adson", "Claudio Spinelli", "Marino", "Matheus França"], "reservas_que_entraram": ["Nuno Moreira", "Claudio Spinelli", "Marino"], "substituicoes": [{"jogador_entrou": "Marino", "jogador_saiu": "Johan Rojas", "minuto": 22, "periodo": "2T", "minuto_absoluto": 67}, {"jogador_entrou": "Nuno Moreira", "jogador_saiu": "Tche Tche", "minuto": 24, "periodo": "2T", "minuto_absoluto": 69}, {"jogador_entrou": "Claudio Spinelli", "jogador_saiu": "David", "minuto": 32, "periodo": "2T", "minuto_absoluto": 77}], "nao_relacionados": ["Allan Vitor", "Pablo", "João Vitor", "Walace Falcão", "Avellar"], "lesionados": ["Jair", "Mateus Carvalho", "Brenner"], "suspensos": [], "servindo_selecao": []}','São Januário','21:00','Thiago Mendes',19369,20072,1385294.0,'{"arbitro": "Wagner do Nascimento Magalhaes", "auxiliares": ["Bruno Boschilia", "Luiz Claudio Regazone"], "var": "Rodrigo D''Alonso Ferreira"}');
