INSERT INTO matches VALUES(206677,'14/04/2026','2026-04-14',259325,682,'casa',1,2,'Jogo horrivel do Vasco... time sem vontade, sem querer jogar, mas o craque da partida foi o melhor jogador do Audax Italiano! O senhor Hernán Heras, arbitro da partida que marcou penalti e expulsou o fraco jogador do Vasco, nosso Leo Pele piorado Cuesta.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Carlos Cuesta", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura", "JP"], "Meio-Campista": ["Nuno Moreira", "Marino"], "Atacante": ["Brenner", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Walace Falcão", "Robert Renan", "Cuiabano", "Thiago Mendes", "Tche Tche", "Matheus França", "Johan Rojas", "Andrés Gómez", "Adson", "David"], "reservas_que_entraram": [], "substituicoes": [], "nao_relacionados": ["Allan Vitor", "Pablo", "Phillipe Gabriel", "Breno Vereza", "Bruno André", "João Vitor", "Saldivia", "Alison", "Avellar", "Cauan Barros", "Gustavo Guimarães", "Lukas Zucarello", "Ramon Rique", "Samuel Jesus", "Andrey Fernandes", "Juninho"], "lesionados": ["Jair", "Mateus Carvalho"], "suspensos": [], "servindo_selecao": []}','São Januário','21:00','',12495,13084,719790.0,'{"arbitro": "Hernán Heras", "auxiliares": ["Agustín Berisso", "Andres Nievas"], "var": "Diego Dunajec"}');
