INSERT INTO matches VALUES(206681,'30/04/2026','2026-04-30',259564,682,'casa',3,0,'Renato Gaúcho estava suspenso pela Conmebol; Alexandre Mendes comandou a equipe à beira do campo.',249336,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Saldivia", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura"], "Meio-Campista": ["Ramon Rique", "Johan Rojas", "Nuno Moreira"], "Atacante": ["Adson", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Avellar", "Walace Falcão", "Robert Renan", "Cauan Barros", "Matheus França", "Lukas Zucarello", "Marino", "Brenner", "David"], "reservas_que_entraram": ["Paulo Henrique", "Avellar", "Cauan Barros", "Marino", "Brenner"], "substituicoes": [{"jogador_saiu": "Puma Rodríguez", "jogador_entrou": "Paulo Henrique", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Lucas Piton", "jogador_entrou": "Avellar", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Ramon Rique", "jogador_entrou": "Cauan Barros", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Johan Rojas", "jogador_entrou": "Marino", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Adson", "jogador_entrou": "Brenner", "minuto": 31, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Andrés Gómez", "Breno Vereza", "Bruno André", "Gustavo Guimarães", "João Vitor", "Juninho", "Pablo", "Phillipe Gabriel", "Samuel Jesus"], "lesionados": ["Jair", "Mateus Carvalho", "Thiago Mendes", "Cuiabano"], "suspensos": ["Carlos Cuesta", "JP"], "servindo_selecao": []}','São Januário','19:00','Puma Rodríguez',11954,12543,707458.0,'{"arbitro": "Jesús Valenzuela", "auxiliares": ["Tulio Moreno", "Alberto Ponte"], "var": "Carlos Orbe"}');
INSERT INTO matches VALUES(206682,'03/05/2026','2026-05-03',4371,2174,'fora',2,2,'Vasco buscou empate no fim no Maracanã: Robert Renan diminuiu de cabeça após escanteio de Nuno Moreira e Hugo Moura empatou no último lance após bola de Carlos Cuesta na área. Gol de David no fim do 1º tempo foi anulado por impedimento.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Carlos Cuesta", "Robert Renan"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Cauan Barros", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Puma Rodríguez", "Brenner", "David"]}, "reservas": ["Andrés Gómez", "Claudio Spinelli", "Adson", "Nuno Moreira", "Hugo Moura", "Daniel Fuzato", "Saldivia", "Lucas Freitas", "Avellar", "Tche Tche", "JP", "Marino"], "reservas_que_entraram": ["Andrés Gómez", "Claudio Spinelli", "Adson", "Nuno Moreira", "Hugo Moura"], "substituicoes": [{"jogador_saiu": "David", "jogador_entrou": "Andrés Gómez", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Brenner", "jogador_entrou": "Claudio Spinelli", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Paulo Henrique", "jogador_entrou": "Adson", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Johan Rojas", "jogador_entrou": "Nuno Moreira", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Cauan Barros", "jogador_entrou": "Hugo Moura", "minuto": 36, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Breno Vereza", "Bruno André", "Gustavo Guimarães", "João Vitor", "Juninho", "Lukas Zucarello", "Matheus França", "Pablo", "Phillipe Gabriel", "Ramon Rique", "Samuel Jesus", "Walace Falcão"], "lesionados": ["Cuiabano", "Jair", "Mateus Carvalho"], "suspensos": [], "servindo_selecao": []}','Maracanã','16:00','',NULL,NULL,NULL,'{"arbitro": "Wilton Pereira Sampaio", "auxiliares": ["Bruno Boschilia", "Leone Carvalho Rocha"], "var": "Daniel Nobre Bins"}');
CREATE TABLE match_goals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            match_id INTEGER NOT NULL,
            side TEXT NOT NULL,
            player_id INTEGER,
            player_name TEXT NOT NULL,
            goals INTEGER NOT NULL DEFAULT 1,
            club_name TEXT,
            is_disallowed INTEGER NOT NULL DEFAULT 0, goal_minutes_json TEXT NOT NULL DEFAULT '[]', goal_periods_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY (match_id) REFERENCES matches (id) ON DELETE CASCADE,
            FOREIGN KEY (player_id) REFERENCES players (id)
        );
